"""Builds the Sprints Android app. Run by GitHub Actions; you don't need to run it yourself."""
import base64, json, os, re, shutil, sys

APP_ID = "com.moabd.sprints"
PASS = "sprints-key-2026"
PLUGIN_B64 = ""
KEYSTORE_B64 = ""
ICONS = {"mipmap-mdpi/ic_launcher.png": "", "mipmap-mdpi/ic_launcher_round.png": "", "mipmap-mdpi/ic_launcher_foreground.png": "", "mipmap-hdpi/ic_launcher.png": "", "mipmap-hdpi/ic_launcher_round.png": "", "mipmap-hdpi/ic_launcher_foreground.png": "", "mipmap-xhdpi/ic_launcher.png": "", "mipmap-xhdpi/ic_launcher_round.png": "", "mipmap-xhdpi/ic_launcher_foreground.png": "", "mipmap-xxhdpi/ic_launcher.png": "", "mipmap-xxhdpi/ic_launcher_round.png": "", "mipmap-xxhdpi/ic_launcher_foreground.png": "", "mipmap-xxxhdpi/ic_launcher.png": "", "mipmap-xxxhdpi/ic_launcher_round.png": "", "mipmap-xxxhdpi/ic_launcher_foreground.png": ""}

MAIN_ACTIVITY = """package com.moabd.sprints;

import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        registerPlugin(SprintsPlugin.class);
        super.onCreate(savedInstanceState);
    }
}
"""

SIGNING = """
    signingConfigs {
        release {
            storeFile file("sprints.p12")
            storePassword "%s"
            keyAlias "sprints"
            keyPassword "%s"
            storeType "pkcs12"
        }
    }
    lint {
        checkReleaseBuilds false
        abortOnError false
    }
""" % (PASS, PASS)


def prepare():
    os.makedirs("www", exist_ok=True)
    shutil.copy("index.html", "www/index.html")
    with open("capacitor.config.json", "w") as f:
        json.dump({"appId": APP_ID, "appName": "Sprints", "webDir": "www"}, f)
    print("prepared web files")


def customize():
    app = "android/app"
    main = app + "/src/main"
    jdir = main + "/java/com/moabd/sprints"
    os.makedirs(jdir, exist_ok=True)
    with open(jdir + "/SprintsPlugin.java", "wb") as f:
        f.write(base64.b64decode(PLUGIN_B64))
    with open(jdir + "/MainActivity.java", "w") as f:
        f.write(MAIN_ACTIVITY)

    mpath = main + "/AndroidManifest.xml"
    m = open(mpath).read()
    if "WRITE_CALENDAR" not in m:
        m = m.replace("</manifest>",
            '    <uses-permission android:name="android.permission.READ_CALENDAR" />\n'
            '    <uses-permission android:name="android.permission.WRITE_CALENDAR" />\n</manifest>')
    open(mpath, "w").write(m)

    with open(main + "/res/values/ic_launcher_background.xml", "w") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#1B2533</color>\n</resources>\n')
    for rel, b64 in ICONS.items():
        with open(main + "/res/" + rel, "wb") as f:
            f.write(base64.b64decode(b64))

    with open(app + "/sprints.p12", "wb") as f:
        f.write(base64.b64decode(KEYSTORE_B64))

    gpath = app + "/build.gradle"
    g = open(gpath).read()
    if "signingConfigs" not in g:
        g = g.replace("android {", "android {" + SIGNING, 1)
        bt = g.index("buildTypes {")
        rel = g.index("release {", bt)
        g = g[:rel] + "release {\n            signingConfig signingConfigs.release" + g[rel + len("release {"):]
    run = os.environ.get("GITHUB_RUN_NUMBER", "1")
    g = re.sub(r"versionCode \d+", "versionCode " + run, g, count=1)
    g = re.sub(r'versionName "[^"]*"', 'versionName "1.' + run + '"', g, count=1)
    open(gpath, "w").write(g)
    print("customized android project, version 1." + run)


if __name__ == "__main__":
    {"prepare": prepare, "customize": customize}[sys.argv[1]]()
